primary = {}
replicas = [{}, {}]
lagged = [False, False]

def write(k, v):
    primary[k] = v
    for i, r in enumerate(replicas):
        if not lagged[i]:
            r[k] = v  # log shipped instantly (healthy)

def read(k, replica=0, read_your_writes=False):
    if read_your_writes:
        return primary.get(k), 'primary (read-your-writes)'
    return replicas[replica].get(k), 'replica %d' % replica

write('user:1', 'Ada')
lagged[1] = True
write('user:1', 'Ada Lovelace')
print('replica 0:', read('user:1', 0))
print('replica 1 (lagging):', read('user:1', 1))
print('writer reads own write:', read('user:1', 1, read_your_writes=True))

import random
random.seed(5)
replicas = [{'a': 1}, {'a': 1}, {'a': 1}]

def local_write(rep, k, v):
    replicas[rep][k] = v

def anti_entropy():  # gossip round: pick up missing writes
    for i in range(len(replicas)):
        for j in range(len(replicas)):
            if i != j and random.random() < 0.7:
                replicas[j].update(replicas[i])

local_write(0, 'a', 2)  # write accepted locally, instantly
for round_ in range(4):
    anti_entropy()
    print('round %d:' % round_, [r['a'] for r in replicas])
print('converged:', len({r['a'] for r in replicas}) == 1)

# G-Counter: each node only increments its own slot; merge = element-wise max
class GCounter:
    def __init__(self, node):
        self.node, self.slots = node, {}
    def inc(self):
        self.slots[self.node] = self.slots.get(self.node, 0) + 1
    def merge(self, other):
        for n, v in other.slots.items():
            self.slots[n] = max(self.slots.get(n, 0), v)
    def value(self):
        return sum(self.slots.values())

a, b = GCounter('a'), GCounter('b')
a.inc(); a.inc(); b.inc()
a.merge(b); b.merge(a)  # different orders, same result
print('replica A:', a.value(), '| replica B:', b.value(), '| converged:', a.value() == b.value())

EDGE, ORIGIN = {}, {'/logo.png': 'bytes', '/app.js': 'bytes'}
LAT = {'edge': 15, 'shield': 60, 'origin': 250}  # ms

def fetch(url):
    if url in EDGE:
        return EDGE[url], LAT['edge'], 'edge HIT'
    # miss: fetch from origin through shield, populate edge
    EDGE[url] = ORIGIN[url]
    return EDGE[url], LAT['origin'], 'edge MISS -> origin'

for i in range(2):
    body, ms, how = fetch('/logo.png')
    print('request %d: %s (%d ms)' % (i + 1, how, ms))
print('second user in the region gets the edge copy: 15ms vs 250ms')

import hashlib

REGIONS = {'us-east': 20, 'eu-west': 95, 'ap-south': 170}
healthy = {'us-east': True, 'eu-west': True, 'ap-south': True}

def route(user):
    # nearest healthy region, sticky per user via consistent choice
    cands = [r for r in REGIONS if healthy[r]]
    cands.sort(key=lambda r: REGIONS[r])
    h = int(hashlib.md5(user.encode()).hexdigest(), 16)
    return cands[h % len(cands)] if len(cands) > 1 else cands[0]

healthy['us-east'] = False  # region outage
for u in ['alice', 'bob', 'carol']:
    print('%-5s -> %s (us-east withdrawn by health checks)' % (u, route(u)))

ALLOWED = {'eu-tenant': {'eu-west', 'eu-central'}, 'us-tenant': {'us-east'}}
replicas = {}

def place(tenant, shard):
    regions = ALLOWED[tenant]
    # placement engine: replicas ONLY inside allowed regions
    replicas[shard] = sorted(regions)
    return replicas[shard]

print('eu-tenant shard replicas:', place('eu-tenant', 's1'))
print('us-tenant shard replicas:', place('us-tenant', 's2'))
print('no cross-border copies exist to leak: constraint enforced at placement')
